const root=pathToFileURL(path.resolve('runtime/src')+'/'),load=n=>import(new URL(n,root)),sha=b=>createHash('sha256').update(b).digest('hex');
const [{normalizeHtxAssetReferences,HTX_ASSET_REFERENCE_URL},{parseSupplementalIdentityRegistry},{collectChainSupplyEvidence},{consumeBlockResultContext},{consumeEvidenceV2},{installEvidenceSourceStore,reserveEvidenceSourceAttempts},{HEDERA_SUPPLY_URL}]=await Promise.all(['htx-asset-identity.mjs','supplemental-candidate-context.mjs','chain-supply-evidence.mjs','block-result-context.mjs','evidence-v2.mjs','evidence-source-store.mjs','hedera-primary-supply.mjs'].map(load));
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),run='PRIMARY_NATIVE_QUAL:'+process.env.GITHUB_RUN_ID+':'+process.env.GITHUB_RUN_ATTEMPT,reservation={rows_read:1000,rows_written:64},sources=[],ids=new Set();let reservedHTTP=0,actualHTTP=0;
