const fetch_impl=async(url,init={})=>{if(![HTX_ASSET_REFERENCE_URL,HEDERA_SUPPLY_URL].includes(String(url))||actualHTTP+1>reservedHTTP||actualHTTP>=2)throw Error('UNADMITTED_PRIMARY_SOURCE_TRANSPORT');actualHTTP++;const r=await fetch(url,{...init,redirect:'error'}),body=await r.clone().text();if(Buffer.byteLength(body)>(url===HTX_ASSET_REFERENCE_URL?1500000:32768))throw Error('PRIMARY_SOURCE_BODY_LIMIT');const file=url===HTX_ASSET_REFERENCE_URL?'htx-currencies.json.gz':'hedera-supply.json.gz',bytes=gzipSync(body),received_ts=Date.now();await fs.writeFile('audit-output/primary-source/'+file,bytes);sources.push({url:String(url),http_status:r.status,received_ts,body_sha256:sha(body),gzip_sha256:sha(bytes),file});return r;};
