 await installEvidenceSourceStore(db);const grant=await reserveEvidenceSourceAttempts(db,{source:'HTX_ASSET_REFERENCE',reservation_id:'HTX_ASSET_REFERENCE:'+run,attempts:1,daily_cap:8,now});out.identity_admission=grant;
 if(grant.allowed){reservedHTTP++;const r=await fetch_impl(HTX_ASSET_REFERENCE_URL,{headers:{accept:'application/json'},signal:AbortSignal.timeout(8000)}),raw=await r.json();if(!r.ok)throw Error('HTX_PRIMARY_HTTP_NOT_CLOSED');out.htx_reference_rows=raw.data?.filter(r=>String(r.currency).toUpperCase()==='HBAR');out.identity=normalizeHtxAssetReferences(raw).entries.HBAR;
  if(out.identity?.status==='CLOSED'){const exact=out.identity.identities[0],parsed=parseSupplementalIdentityRegistry({HBAR:exact}).entries.HBAR?.identity;out.parsed_identity=parsed;out.supply=await collectChainSupplyEvidence({db,fetch_impl,request_admit,contract:'HBAR-USDT',run_id:run,asset_identity:parsed,now:Date.now(),clock:Date.now});out.consumer=consumeBlockResultContext({evidence:out.supply.evidence,contract:'HBAR-USDT',now:Date.now()});out.score_adjustment=consumeEvidenceV2(out.supply.evidence,{decision_ts:Date.now(),base_interest:70}).adjustment;}
 }
